{"metadata":{"kernelspec":{"name":"ir","display_name":"R","language":"R"},"language_info":{"mimetype":"text/x-r-source","name":"R","pygments_lexer":"r","version":"3.6.0","file_extension":".r","codemirror_mode":"r"}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# =========================================================================\n# PLOS ONE MAJOR COMMENT #2 VALIDATION PIPELINE: FULL TCGA-BRCA COHORT\n# =========================================================================\n\n# 1. Install and load necessary libraries smoothly\nif (!requireNamespace(\"BiocManager\", quietly = TRUE)) {\n    install.packages(\"BiocManager\")\n}\nBiocManager::install(c(\"TCGAbiolinks\", \"DESeq2\", \"EnhancedVolcano\"), \n                     update = FALSE, ask = FALSE)\n\nlibrary(TCGAbiolinks)\nlibrary(DESeq2)\nlibrary(EnhancedVolcano)\n\n# 2. Query and Download the full TCGA-BRCA Cohort (No downsampling)\nquery_brca <- GDCquery(\n  project = \"TCGA-BRCA\",\n  data.category = \"Transcriptome Profiling\",\n  data.type = \"Gene Expression Quantification\",\n  workflow.type = \"STAR - Counts\"\n)\nGDCdownload(query_brca, method = \"api\", files.per.chunk = 40)\nbrca_data <- GDCprepare(query_brca)\n\n# 3. Format design variables cleanly as a factor\n# Using the correct direct SummarizedExperiment metadata structure\ncolData(brca_data)$sample_type <- as.factor(colData(brca_data)$sample_type)\n\n# 4. Build the design matrix object and run the pipeline\ndds <- DESeqDataSet(brca_data, design = ~ sample_type)\n\n# Pre-filter low counts to dramatically optimize execution memory\nkeep <- rowSums(counts(dds)) >= 10\ndds <- dds[keep, ]\n\n# Run the primary differential expression analysis\ndds <- DESeq(dds)\nres_full <- results(dds) \n\n# 5. Export progress results sheet\nwrite.csv(as.data.frame(res_full), \"TCGA_BRCA_Full_DEGs.csv\")\n\n# 6. Target verification tracking execution\nres2 <- res_full[!is.na(res_full$padj), ]\nsig  <- res2[res2$padj < 0.05 & abs(res2$log2FoldChange) > 1, ]\n\ncat(\"\\n================ RESULTS SUMMARY ================\\n\")\ncat(\"Full-cohort genes tested:\", nrow(res2), \"\\n\")\ncat(\"Full-cohort significant DEGs:\", nrow(sig), \"\\n\")\ncat(\"  Up:\", sum(sig$log2FoldChange > 0), \" Down:\", sum(sig$log2FoldChange < 0), \"\\n\\n\")\n\ntargets <- c(\"ENSG00000099953\"=\"MMP11\",\"ENSG00000123500\"=\"COL10A1\",\"ENSG00000060718\"=\"COL11A1\",\n             \"ENSG00000119927\"=\"GPAM\",\"ENSG00000117650\"=\"NEK2\",\"ENSG00000105974\"=\"CAV1\",\n             \"ENSG00000025423\"=\"HSD17B6\",\"ENSG00000090889\"=\"KIF4A\",\"ENSG00000077152\"=\"UBE2T\")\n\nfor (ens in names(targets)) {\n  row <- res_full[grepl(ens, rownames(res_full)), ]\n  if (nrow(row) > 0) {\n    cat(targets[ens], \": log2FC =\", round(row$log2FoldChange,3), \n        \" padj =\", format(row$padj, scientific=TRUE), \"\\n\")\n  } else {\n    cat(targets[ens], \": Not found in full matrix\\n\")\n  }\n}\ncat(\"=================================================\\n\")\n","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null}]}